/**
 * Machines wave 3 (4 November 2026, owner request: "did we track down all the machine types used for radiation, chemo
 * seats re comfort, hair preservation machines and their chain of development and improvement ideas?"). The model lines
 * behind the family records of src/data/machines-wave.ts and machines-wave2.ts, read from the regulator's own records:
 * every 510(k) and De Novo number below was read from the openFDA device API and its accessdata.fda.gov page on
 * 4 November 2026; model claims are quoted from the maker's page or the 510(k) summary; trial figures from the
 * ClinicalTrials.gov v2 API and the paper abstracts as Europe PMC returns them.
 *
 * What is here: machine types the corpus lacked (upright positioning, intraoperative radiotherapy machines, electronic
 * brachytherapy, rotating gamma systems, infusion chairs, limb cryocompression, manual cold caps), the makers that
 * hold the clearances, the scalp-cooling, neuropathy-prevention and FLASH trials, five roadmaps of dated model
 * generations, and improvement ideas where a source names the unmet need. The family records themselves gained their
 * model lists and regulator links in place. Every new technology is aliased in
 * src/data/schematic-aliases/machines-wave3.ts to an existing drawing of the same mechanism.
 *
 * What a model's first FDA record means here: the earliest 510(k) whose device name carries that model. Some models were
 * marketed earlier under an umbrella clearance, and a 510(k) is the agency's finding of substantial equivalence, not an
 * approval and not evidence that the machine improves outcomes.
 */
import type { CompanyInput, IdeaInput, RoadmapInput, TechnologyInput, TrialInput } from "@/lib/schema";

const asOf = "2026-11-04";
const tags = ["machines-wave3"];
const provenance = { editedBy: "OnCo machines inventory (openFDA, accessdata.fda.gov, ClinicalTrials.gov v2, Europe PMC, maker pages)", editedOn: asOf };

/** An FDA 510(k) record page. */
export const fda510k = (k: string, what: string) => ({ label: `FDA 510(k) ${k}: ${what}`, url: `https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpmn/pmn.cfm?ID=${k}` });
/** An FDA De Novo record page. */
export const fdaDeNovo = (den: string, what: string) => ({ label: `FDA De Novo ${den}: ${what}`, url: `https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpmn/denovo.cfm?id=${den}` });
const ct = (nct: string) => ({ label: `ClinicalTrials.gov ${nct}`, url: `https://clinicaltrials.gov/study/${nct}` });
const doi = (label: string, d: string) => ({ label, url: `https://doi.org/${d}` });

type Tc = Omit<TechnologyInput, "kind" | "asOf">;
const tech = (x: Tc): TechnologyInput => ({ kind: "technology", asOf, tags, provenance, ...x } as TechnologyInput);
type Co = Omit<CompanyInput, "kind" | "asOf">;
const co = (x: Co): CompanyInput => ({ kind: "company", asOf, tags, provenance, ...x } as CompanyInput);
type Tr = Omit<TrialInput, "kind" | "asOf">;
const trial = (x: Tr): TrialInput => ({ kind: "trial", asOf, tags, provenance, ...x } as TrialInput);
type Rm = Omit<RoadmapInput, "kind" | "asOf">;
const roadmap = (x: Rm): RoadmapInput => ({ kind: "roadmap", asOf, tags, provenance, ...x } as RoadmapInput);
type Id = Omit<IdeaInput, "kind" | "asOf">;
const idea = (x: Id): IdeaInput => ({ kind: "idea", asOf, tags: [...tags, "proposal"], provenance, ...x } as IdeaInput);

